// This file provides the query entry point over the materialized profile
// bundle committed at modelprofiles/profiles.json. The bundle is generated by
// the CLI's materialize command:
//
//	go run ./cmd/langchain-profiles materialize
//
// which fetches live data from models.dev for each provider and merges the
// upstream-mirrored augmentations in modelprofiles/data/<provider>/
// profile_augmentations.toml. Regenerate it after changing an augmentations
// file; tests read the committed bundle, so they stay offline.

package modelprofiles

import (
	_ "embed"
	"encoding/json"
	"sync"
)

// profilesJSON is the materialized provider-to-registry bundle produced by
// `langchain-profiles materialize`. Shape:
// {"<provider>": {"<model-id>": {<profile fields>}}}.
//
//go:embed profiles.json
var profilesJSON []byte

// materialized lazily decodes the embedded bundle once per process. A decode
// failure (which would mean the committed file is corrupt) yields an empty
// bundle so every Lookup misses rather than panicking; the committed file is
// covered by tests, so this should be unreachable.
var materialized = sync.OnceValue(func() map[string]Registry {
	var registries map[string]Registry
	if err := json.Unmarshal(profilesJSON, &registries); err != nil {
		return map[string]Registry{}
	}
	return registries
})

// Lookup returns the materialized model profile for the given models.dev
// provider ID (e.g. "anthropic", "openai") and model ID (e.g.
// "claude-sonnet-4-6"), reading the profiles.json bundle committed with this
// package. The second return value reports whether both the provider and the
// model ID are present in the bundle.
//
// IDs are matched exactly; callers that need fuzzy matching (for example,
// stripping date suffixes from model names) must normalize the model ID
// before calling. The returned Profile is shared read-only state backed by the
// embedded bundle and must not be mutated.
//
// Boolean capability flags are read with Profile.Supports; to distinguish an
// absent flag from an explicit false (upstream declares
// mid_conversation_tools = false for some models, e.g. claude-sonnet-5), do a
// direct map lookup on the returned Profile instead.
func Lookup(provider, model string) (Profile, bool) {
	registry, ok := materialized()[provider]
	if !ok {
		return nil, false
	}
	profile, ok := registry[model]
	if !ok {
		return nil, false
	}
	return profile, true
}
